<?phpnamespace Database\Seeders;use App\Models\Category;use App\Models\Comment;use App\Models\ContactMessage;use App\Models\Faq;use App\Models\NavigationItem;use App\Models\Page;use App\Models\Post;use App\Models\Setting;use App\Models\User;use App\Models\Advertisement;use Illuminate\Database\Seeder;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;class DatabaseSeeder extends Seeder{    public function run(): void    {        // Admin user        $admin = User::firstOrCreate(            ['email' => 'admin@huvanti.com'],            [                'name' => 'Huvanti Admin',                'password' => Hash::make('Huvanti@2026'),                'role' => 'admin',                'bio' => 'Founder & Editor-in-Chief at Huvanti. Passionate about sharing knowledge across technology, lifestyle, health, travel and finance.',                'email_verified_at' => now(),            ]        );        // Categories - multi-niche - deep green palette consistent with primary #14532d        $categories = [            ['name'=>'Technology','slug'=>'technology','description'=>'Latest in tech AI gadgets and software','color'=>'#14532d','icon'=>'cpu'],            ['name'=>'Health & Wellness','slug'=>'health-wellness','description'=>'Fitness nutrition and mental health','color'=>'#0f3d22','icon'=>'heart-pulse'],            ['name'=>'Finance','slug'=>'finance','description'=>'Money investing and personal finance','color'=>'#1b4332','icon'=>'wallet'],            ['name'=>'Travel','slug'=>'travel','description'=>'Destinations guides and travel tips','color'=>'#0f5132','icon'=>'plane'],            ['name'=>'Lifestyle','slug'=>'lifestyle','description'=>'Culture food and everyday inspiration','color'=>'#164e3b','icon'=>'sparkles'],            ['name'=>'Education','slug'=>'education','description'=>'Learning career and skill development','color'=>'#1a3a2a','icon'=>'book'],            // Additional categories (kept in sync with the            // 2026_08_25_000001_add_more_categories migration for live sites)            ['name'=>'Business','slug'=>'business','description'=>'Entrepreneurship startups marketing and business strategy','color'=>'#0C3B2E','icon'=>'briefcase'],            ['name'=>'Entertainment','slug'=>'entertainment','description'=>'Movies music celebrities and pop culture','color'=>'#0C3B2E','icon'=>'film'],            ['name'=>'Sports','slug'=>'sports','description'=>'Match analysis fitness tips and sports news','color'=>'#0C3B2E','icon'=>'dumbbell'],            ['name'=>'Food & Recipes','slug'=>'food-recipes','description'=>'Cooking guides restaurant reviews and kitchen tips','color'=>'#0C3B2E','icon'=>'utensils'],            ['name'=>'Science','slug'=>'science','description'=>'Discoveries research and how the universe works','color'=>'#0C3B2E','icon'=>'flask-conical'],            ['name'=>'Gaming','slug'=>'gaming','description'=>'Game reviews esports and gaming hardware','color'=>'#0C3B2E','icon'=>'tv'],            ['name'=>'Automotive','slug'=>'automotive','description'=>'Car reviews maintenance tips and industry news','color'=>'#0C3B2E','icon'=>'car'],            ['name'=>'World News','slug'=>'world-news','description'=>'Breaking headlines and global affairs explained','color'=>'#0C3B2E','icon'=>'globe'],            ['name'=>'Home & DIY','slug'=>'home-diy','description'=>'Interior ideas improvement projects and how-to guides','color'=>'#0C3B2E','icon'=>'puzzle'],            ['name'=>'Personal Growth','slug'=>'personal-growth','description'=>'Productivity habits and building a better you','color'=>'#0C3B2E','icon'=>'lightbulb'],        ];        foreach($categories as $i=>$c){            Category::firstOrCreate(['slug'=>$c['slug']], array_merge($c, ['sort_order'=>$i]));        }        // Settings        $settings = [            ['key'=>'site_name','value'=>'Huvanti','group'=>'general'],            ['key'=>'site_tagline','value'=>'Explore Ideas. Inspire Life.','group'=>'general'],            ['key'=>'site_description','value'=>'Huvanti is a multi-niche blog covering technology, health, finance, travel, lifestyle and education with expert insights and curated stories.','group'=>'general'],            ['key'=>'site_keywords','value'=>'huvanti, blog, multi niche, technology, health, finance, travel','group'=>'seo'],            ['key'=>'site_logo','value'=>'','group'=>'general'],            ['key'=>'contact_email','value'=>'hello@huvanti.com','group'=>'general'],            ['key'=>'footer_copyright','value'=>'2026-27, All Rights Reserved','group'=>'footer'],            ['key'=>'ads_sidebar_code','value'=>'','group'=>'ads'],        ];        foreach($settings as $s){            Setting::updateOrCreate(['key'=>$s['key']], $s);        }        // Pages        $pages = [            ['title'=>'Privacy Policy','slug'=>'privacy-policy','content'=>'<h2>Privacy Policy</h2><p>Last updated: August 2026</p><p>Huvanti respects your privacy. This policy explains what information we collect, how we use it, and what choices you have. By using huvanti.com you agree to the practices described here.</p><h3>Information we collect</h3><p>We collect information you provide directly. This includes your name and email when you contact us, leave a comment, or create an author account. We also collect technical information automatically. This includes your IP address, browser type, device type, pages viewed, and approximate location. We collect this to keep the site secure and to understand which content is helpful.</p><h3>How we use your information</h3><p>We use your information to operate the site, respond to your messages, moderate comments, manage accounts, improve content, and measure audience. We do not sell your personal information.</p><h3>Cookies</h3><p>We use cookies to remember preferences and to analyze traffic. You can control cookies in your browser settings. See our Cookie Policy for details.</p><h3>Sharing</h3><p>We share data only when needed. This includes service providers who help us run the site, legal authorities when required by law, and successors if the site is transferred. All partners must protect your data.</p><h3>Your rights</h3><p>You may request access, correction, or deletion of your personal data. You may also object to certain processing. To exercise these rights, contact us through the contact page. We will respond within a reasonable time.</p><h3>Data retention and security</h3><p>We keep personal data only as long as needed for the purpose it was collected. We use reasonable technical and organizational measures to protect it, but no system is completely secure.</p><h3>Contact and updates</h3><p>If you have questions about this policy, use the contact page to reach us. We may update this policy from time to time. We will post the new version here and update the date at the top.</p>'],            ['title'=>'Terms and Conditions','slug'=>'terms-conditions','content'=>'<h2>Terms and Conditions</h2><p>Last updated: August 2026</p><p>These terms govern your use of huvanti.com. By accessing the site you agree to them. If you do not agree, please do not use the site.</p><h3>Use of the site</h3><p>You may use the site for personal and lawful purposes. You must not attempt to disrupt the site, gain unauthorized access, or use automated systems to extract content at scale.</p><h3>Intellectual property</h3><p>All articles, images, logos, and design on Huvanti belong to Huvanti or its licensors unless stated otherwise. You may share links and short quotes with attribution. You may not copy or republish substantial content without permission.</p><h3>User content</h3><p>If you submit posts, comments, or other content, you confirm that it is yours and does not infringe the rights of others. You grant Huvanti a license to display that content on the site. Published posts may remain visible even if your account is later removed.</p><h3>Accuracy and availability</h3><p>We work to keep information accurate and the site available, but we do not guarantee that content is complete or error free, or that the site will be uninterrupted.</p><h3>External links and affiliates</h3><p>The site may contain links to third party sites and affiliate links. We are not responsible for the content or practices of those sites. Any affiliate relationship is disclosed on the relevant page.</p><h3>Limitation of liability</h3><p>To the extent permitted by law, Huvanti is not liable for damages arising from your use of the site. Content is provided for general information and is not professional advice.</p><h3>Changes</h3><p>We may update these terms from time to time. The updated version will be posted here. Continued use after changes means you accept the new terms.</p>'],            ['title'=>'Cookie Policy','slug'=>'cookie-policy','content'=>'<h2>Cookie Policy</h2><p>Last updated: August 2026</p><p>This policy explains how Huvanti uses cookies and similar technologies on huvanti.com.</p><h3>What are cookies</h3><p>Cookies are small text files stored on your device when you visit a site. They help the site remember your preferences and understand how visitors use it.</p><h3>How we use cookies</h3><p>We use necessary cookies to make the site work. We use preference cookies to remember your theme choice. We use analytics cookies to see which pages are popular and how visitors move through the site. We may use advertising cookies only if ads are enabled, to measure ad performance.</p><h3>Managing cookies</h3><p>You can control cookies through your browser settings. You can block or delete cookies at any time. If you block necessary cookies, some parts of the site may not work correctly.</p><h3>More information</h3><p>If you have questions about our use of cookies, contact us through the contact page. Also see our Privacy Policy for how we handle personal data.</p>'],            ['title'=>'About Us','slug'=>'about','content'=>'<h2>About Huvanti</h2><p>Huvanti is an independent online publication. We write practical, easy to read articles across technology, health and wellness, finance, travel, lifestyle, and education. One topic at a time, explained in plain language.</p><h3>What we cover</h3><p>Technology explains the tools and trends shaping daily life in plain language. Health and Wellness offers practical guidance on food, sleep, fitness, and focus that is grounded in evidence and real experience. Finance breaks down saving, investing, and money habits into steps you can act on. Travel covers meaningful destinations and smarter planning. Lifestyle explores calm and intentional living. Education shares learning methods that actually help you retain knowledge.</p><h3>How we work</h3><p>Every article is drafted, reviewed, and checked before publication. When we cite studies or data, we link to the source so you can verify it. When information changes, we update the article and note the change. We read every comment and every message.</p><h3>Our mission</h3><p>We aim to explore ideas that matter and inspire life through clear and human centered writing. Success for us is a reader finishing an article knowing something useful they did not know before.</p><h3>Our promise</h3><p>No clickbait. No filler. No fake urgency. If we recommend something, it is because we believe it helps you, not because someone paid us to say so. Where affiliate links appear, they are disclosed clearly on the page.</p><h3>Talk to us</h3><p>Questions, corrections and ideas are always welcome. Reach us any time through the <a href="/contact">contact page</a>.</p>'],            ['title'=>'Contact','slug'=>'contact','content'=>'<h2>Contact Huvanti</h2><p>We welcome your questions, feedback, and ideas. Use the form on this page to send us a message. We read every submission and reply as soon as we can.</p><h3>What to include</h3><p>For general feedback, tell us which article or page you are referring to. For editorial concerns, please describe the issue and include a link. For business inquiries, briefly describe your proposal.</p><h3>Response time</h3><p>We aim to reply within two business days. Response time may be longer during busy periods.</p>'],            ['title'=>'Editorial Policy','slug'=>'editorial-policy','content'=>'<h2>Editorial Policy</h2><p>Last updated: August 2026</p><p>This policy explains how Huvanti creates, reviews, and maintains content. Our goal is to be accurate, independent, and useful.</p><h3>How we write</h3><p>Every article begins with a question a real reader would ask. We research the answer, test claims where possible, and write in clear language. Writers draw from direct experience with the products, places, and techniques they cover.</p><h3>Sourcing and accuracy</h3><p>When we cite studies, statistics, or news, we link to the original source so you can verify it. Facts are checked before publication. If we cannot verify a claim, we state this clearly or omit it.</p><h3>Independence</h3><p>Advertisers and affiliate partners have no influence on what we write or how we rate anything. Commissions never affect recommendations. If a product is not good, we say so even when we could earn from it.</p><h3>Use of AI tools</h3><p>We may use AI tools for grammar and research support in the same way a writer uses a spell checker. Every published article is written, reviewed, and approved by a human editor who takes responsibility for it. We do not publish unreviewed machine generated text.</p><h3>Corrections</h3><p>Mistakes can happen. When an error is found, we correct the article and note the change. You can report an issue at any time through the contact page.</p><h3>Author standards</h3><p>Contributing authors follow our posting rules. Work must be original, honest, and free of filler. Every submission receives human review before it can be published.</p>'],        ];        foreach($pages as $p){            Page::firstOrCreate(['slug'=>$p['slug']], array_merge($p, ['status'=>'published']));        }        // Navigation        $navItems = [            ['label'=>'Home','url'=>'/','position'=>'header','sort_order'=>1],            ['label'=>'Categories','url'=>'/#categories','position'=>'header','sort_order'=>2],            ['label'=>'Blog','url'=>'/blog','position'=>'header','sort_order'=>3],            ['label'=>'About','url'=>'/about','position'=>'header','sort_order'=>4],            ['label'=>'Contact','url'=>'/contact','position'=>'header','sort_order'=>5],            // mobile same but allow separate control            ['label'=>'Home','url'=>'/','position'=>'mobile','sort_order'=>1],            ['label'=>'Categories','url'=>'/#categories','position'=>'mobile','sort_order'=>2],            ['label'=>'Blog','url'=>'/blog','position'=>'mobile','sort_order'=>3],            ['label'=>'About','url'=>'/about','position'=>'mobile','sort_order'=>4],            ['label'=>'Contact','url'=>'/contact','position'=>'mobile','sort_order'=>5],        ];        foreach($navItems as $n){ NavigationItem::firstOrCreate(['label'=>$n['label'],'position'=>$n['position']], $n); }        // Ads        Advertisement::firstOrCreate(['title'=>'Sidebar Ad 300x250'], ['position'=>'sidebar','code'=>'<div style="background:#f3f4f6;border:2px dashed #d1d5db;border-radius:12px;height:250px;display:flex;align-items:center;justify-content:center;color:#6b7280">Advertisement 300x250</div>','is_active'=>true,'sort_order'=>1]);        Advertisement::firstOrCreate(['title'=>'Inline Ad'], ['position'=>'in_article','code'=>'<div style="background:#fffbeb;border:2px dashed #f59e0b;border-radius:12px;height:90px;display:flex;align-items:center;justify-content:center;color:#92400e">Advertisement Zone</div>','is_active'=>true,'sort_order'=>1]);        // Posts - sample 8 posts across categories        $cats = Category::all()->keyBy('slug');        $samplePosts = [            [                'title'=>'The Future of AI: 7 Trends That Will Shape 2027',                'slug'=>'future-of-ai-trends-2027',                'excerpt'=>'From generative agents to edge AI, discover the breakthrough trends redefining how we live and work.',                'category'=>'technology',                'views'=>0,                'is_featured'=>true,                'content'=>'<h2>Introduction</h2><p>Artificial intelligence is no longer a futuristic promise — it is the operating system of modern life. In 2026-27, we are witnessing a convergence of large models, efficient chips and real-world deployment.</p><h2>1. Generative Agents</h2><p>AI agents that can plan, use tools and collaborate are moving from demos to daily workflows.</p><h3>Why it matters</h3><p>Businesses report 40% productivity gains where agents are correctly integrated.</p><h2>2. Edge AI</h2><p>On-device models reduce latency and privacy concerns. Your phone now runs models that previously needed a data center.</p><h2>3. AI in Healthcare</h2><p>Diagnostic models are achieving specialist-level accuracy while remaining interpretable.</p><p>Stay tuned as we explore deeper use cases in the coming months.</p>',                'faqs'=>[                    ['q'=>'Is AI going to replace jobs?','a'=>'AI will transform jobs rather than eliminate them. Roles that involve routine pattern recognition are most affected, while creative and interpersonal roles grow.'],                    ['q'=>'What is Edge AI?','a'=>'Edge AI runs models directly on devices (phone, laptop, sensor) instead of the cloud, offering faster response and better privacy.'],                ]            ],            [                'title'=>'Minimalist Morning Routines for More Focus and Energy',                'slug'=>'minimalist-morning-routines-focus-energy',                'excerpt'=>'A simple 30-minute routine that improves focus, mood and metabolic health — without overwhelm.',                'category'=>'health-wellness',                'content'=>'<h2>Why Mornings Matter</h2><p>How you start the day sets your hormonal rhythm. A calm, intentional morning reduces cortisol spikes and improves decision making.</p><h2>The 4-Step Routine</h2><p><strong>1. Light:</strong> Get natural light within 10 minutes of waking.<br><strong>2. Movement:</strong> 5 minutes of mobility or walk.<br><strong>3. Mind:</strong> 2 minutes breathing or journaling.<br><strong>4. Fuel:</strong> Protein + fiber before caffeine.</p><h3>Tracking Progress</h3><p>Use a simple habit tracker. Consistency beats intensity.</p>',                'faqs'=>[                    ['q'=>'How long until I see results?','a'=>'Most people notice better energy within 7-10 days. Sleep quality often improves first.'],                ]            ],            [                'title'=>'Smart Investing for Beginners: Building Wealth in Your 20s and 30s',                'slug'=>'smart-investing-beginners-building-wealth',                'excerpt'=>'No jargon, just practical steps to start investing with small amounts and avoid common mistakes.',                'category'=>'finance',                'content'=>'<h2>Start with Why</h2><p>Investing is not about picking winners; it is about time, diversification and behavior.</p><h2>The Core Principles</h2><p>Diversify across index funds, keep fees low, automate contributions and stay invested.</p><h3>An Example</h3><p>$200/month at 7% annual return becomes ~$240k in 30 years.</p><h2>Common Mistakes</h2><p>Chasing hype, panic selling and ignoring emergency funds derail most beginners.</p>',                'faqs'=>[                    ['q'=>'How much should I invest to start?','a'=>'Start with what you can afford consistently — even $10-50/month builds the habit and benefits from compounding.'],                    ['q'=>'Is crypto a good investment?','a'=>'Crypto is high risk and volatile. Treat it as a small satellite, not the core of your portfolio.'],                ]            ],            [                'title'=>'Hidden Gems of Southeast Asia: 5 Islands Without the Crowds',                'slug'=>'hidden-gems-southeast-asia-islands',                'excerpt'=>'Crystal water, local food and quiet beaches — our curated list for slow travel lovers.',                'category'=>'travel',                'content'=>'<h2>Why Go Off the Beaten Path?</h2><p>Overtourism strains locals. These islands offer culture, nature and space to breathe.</p><h2>1. Koh Rong Sanloem, Cambodia</h2><p>Bioluminescent waters and jungle trails.</p><h2>2. Siargao, Philippines (North)</h2><p>Surf, lagoons and community-run stays.</p><h2>3. Pulau Weh, Indonesia</h2><p>World-class diving without Bali prices.</p>',                'faqs'=>[                    ['q'=>'Best time to visit?','a'=>'November to April offers dry season across most of these islands.'],                ]            ],            [                'title'=>'The Art of Slow Living: Designing a Home That Calms Your Mind',                'slug'=>'art-of-slow-living-designing-home-calms-mind',                'excerpt'=>'How texture, light and negative space can turn your home into a restorative sanctuary.',                'category'=>'lifestyle',                'content'=>'<h2>Slow Living at Home</h2><p>Our homes shape our nervous system. Choice of materials, light and clutter directly affect stress.</p><h3>Three Principles</h3><p>Natural materials, soft light layers and visible empty space.</p><h2>Start Small</h2><p>Clear one surface, add a linen texture and a warm lamp. Notice how your breath changes.</p>',                'faqs'=>[]            ],            [                'title'=>'Learn Anything Faster: The Spaced Repetition Playbook',                'slug'=>'learn-anything-faster-spaced-repetition',                'excerpt'=>'Neuroscience-backed techniques to remember more in less time — for students and professionals.',                'category'=>'education',                'content'=>'<h2>The Forgetting Curve</h2><p>We forget 70% within 24 hours unless we reactivate memory. Spaced repetition fixes this.</p><h2>How to Apply</h2><p>Test yourself before re-reading, space intervals (1d, 3d, 7d, 14d), and use active recall cards.</p><h3>Tools</h3><p>Anki, RemNote or even pen-and-paper boxes work — the system matters more than the app.</p>',                'faqs'=>[                    ['q'=>'Does cramming ever work?','a'=>'Cramming helps short-term recall for an exam but fails for long-term retention. Spacing wins for durable learning.'],                ]            ],            [                'title'=>'Balanced Eating on a Budget: 7-Day High-Protein Meal Plan',                'slug'=>'balanced-eating-budget-high-protein-meal-plan',                'excerpt'=>'Nutritious, affordable and time-saving meals designed for busy professionals.',                'category'=>'health-wellness',                'views'=>0,                'is_featured'=>true,                'content'=>'<h2>Principles</h2><p>Budget eating does not mean boring. Focus on eggs, legumes, frozen veg and whole grains.</p><h2>Sample Day</h2><p>Breakfast: Greek yogurt + oats. Lunch: Chickpea salad. Dinner: Stir-fry tofu + brown rice.</p><h3>Shopping Tip</h3><p>Buy in bulk, cook 2x per week, and freeze portions.</p>',                'faqs'=>[]            ],            [                'title'=>'Remote Work Productivity: Deep Work in a Distracted World',                'slug'=>'remote-work-productivity-deep-work',                'excerpt'=>'Master attention, async communication and rituals to thrive while working from anywhere.',                'category'=>'technology',                'content'=>'<h2>The Attention Economy</h2><p>Distraction is the default. Deep work requires design, not willpower.</p><h2>System</h2><p>Time-block 90-minute focus sessions, batch messages twice daily, and end with a shutdown ritual.</p>',                'faqs'=>[]            ],        ];        foreach($samplePosts as $sp){            $cat = $cats[$sp['category']] ?? $cats->first();            $post = Post::firstOrCreate(['slug'=>$sp['slug']], [                'title'=>$sp['title'],                'excerpt'=>$sp['excerpt'],                'content'=>$sp['content'],                'category_id'=>$cat->id,                'user_id'=>$admin->id,                'author_name'=>'Joe Goldberg',                'author_bio'=>'Senior Editor at Huvanti covering technology, health and modern culture. Passionate about clear, human-centered storytelling.',                'reading_time'=> ceil(str_word_count(strip_tags($sp['content']))/200),                'status'=>'published',                'published_at'=> now()->subDays(rand(1,20)),                'meta_title'=>$sp['title'].' | Huvanti',                'meta_description'=>$sp['excerpt'],                'views'=>0,                'is_featured'=>$sp['is_featured'] ?? false,                'featured_image'=> 'https://picsum.photos/seed/'.Str::slug($sp['slug']).'/800/450',            ]);            foreach($sp['faqs'] as $idx=>$f){                Faq::firstOrCreate(['post_id'=>$post->id,'question'=>$f['q']], ['answer'=>$f['a'],'sort_order'=>$idx]);            }        }    }}